# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
from flag_gems.runtime import torch_device_fn

"""Elementwise least-common-multiple (lcm) in Triton.

Semantics (FlagGems/torch reference intent):
    lcm(a, b) = (|a| // gcd(|a|, |b|)) * |b|   computed with unsigned
    arithmetic in the promoted element width and then truncated/reinterpreted
    to the output dtype; lcm(_, 0) = lcm(0, _) = 0.

gcd(|a|,|b|) uses the Euclidean algorithm in the unsigned domain. The inner
loop performs two dependent Euclid steps per iteration (halving loop-control
overhead); the iteration count is a conservative ceiling on steps/2 for the
dtype width (int8: 8 pairs, int16: 13 pairs, <=32-bit: 24 pairs,
64-bit: 48 pairs). Already-finished lanes stay inert via masking.

Broadcast / non-contiguous operands are resolved in-kernel by decomposing the
flat output index into coordinates (innermost first) with per-dim metadata;
no framework data movement contributes to the returned values.
"""

import torch
import triton
import triton.language as tl

_MAXD = 6
_BLOCK32 = 2048
_WARPS32 = 8
_BLOCK64 = 512
_WARPS64 = 4
# iteration counts = (max Euclid steps for the dtype) / 2, rounded up
_K = {torch.int8: 8, torch.int16: 13, torch.int32: 24, torch.int64: 48}


@triton.jit
def _eu2_u32(ma, mb, K: tl.constexpr):
    """Two-step Euclid in u32 domain; returns gcd (0 when both zero)."""
    aa = ma
    bb = mb
    for _ in range(K):
        act = bb != 0
        bs = tl.where(act, bb, 1)
        md = aa % bs
        aa = tl.where(act, bb, aa)
        bb = tl.where(act, md, bb)
        act = bb != 0
        bs = tl.where(act, bb, 1)
        md = aa % bs
        aa = tl.where(act, bb, aa)
        bb = tl.where(act, md, bb)
    return aa


@triton.jit
def _eu2_u64(ma, mb, K: tl.constexpr):
    """Two-step Euclid in u64 domain; returns gcd (0 when both zero)."""
    aa = ma
    bb = mb
    for _ in range(K):
        act = bb != 0
        bs = tl.where(act, bb, 1)
        md = aa % bs
        aa = tl.where(act, bb, aa)
        bb = tl.where(act, md, bb)
        act = bb != 0
        bs = tl.where(act, bb, 1)
        md = aa % bs
        aa = tl.where(act, bb, aa)
        bb = tl.where(act, md, bb)
    return aa


@triton.jit
def _finish32(ma, mb, g):
    gs = tl.where(g == 0, 1, g)
    r = (ma // gs) * mb
    return r.to(tl.int32)


@triton.jit
def _finish64(ma, mb, g):
    gs = tl.where(g == 0, 1, g)
    r = (ma // gs) * mb
    return r.to(tl.int64)


# ---------------------------------------------------------------------------
# flat kernels (contiguous, same shape)
# ---------------------------------------------------------------------------
@triton.jit
def _lcm_flat32(a_ptr, b_ptr, o_ptr, numel, BLOCK: tl.constexpr, K: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < numel
    x = tl.load(a_ptr + offs, mask=m, other=0).to(tl.int32)
    y = tl.load(b_ptr + offs, mask=m, other=0).to(tl.int32)
    xa = x.to(tl.uint32)
    ya = y.to(tl.uint32)
    ma = tl.where(x < 0, 0 - xa, xa)
    mb = tl.where(y < 0, 0 - ya, ya)
    g = _eu2_u32(ma, mb, K)
    r = _finish32(ma, mb, g)
    tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty), mask=m)


@triton.jit
def _lcm_flat64(a_ptr, b_ptr, o_ptr, numel, BLOCK: tl.constexpr, K: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < numel
    x = tl.load(a_ptr + offs, mask=m, other=0).to(tl.int64)
    y = tl.load(b_ptr + offs, mask=m, other=0).to(tl.int64)
    xa = x.to(tl.uint64)
    ya = y.to(tl.uint64)
    ma = tl.where(x < 0, 0 - xa, xa)
    mb = tl.where(y < 0, 0 - ya, ya)
    g = _eu2_u64(ma, mb, K)
    r = _finish64(ma, mb, g)
    tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty), mask=m)


# ---------------------------------------------------------------------------
# broadcast kernels.
# meta (int32 tensor) with dims innermost-first:
#   meta[0..MAXD)        out dims (reversed)
#   meta[MAXD..2MAXD)    a effective strides (reversed)
#   meta[2MAXD..3MAXD)   b effective strides (reversed)
# padding: dim 1, stride 0.
# ---------------------------------------------------------------------------
@triton.jit
def _lcm_bcast32(
    a_ptr,
    b_ptr,
    o_ptr,
    numel,
    meta_ptr,
    BLOCK: tl.constexpr,
    K: tl.constexpr,
    MAXD: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < numel
    rem = offs
    oa = tl.zeros([BLOCK], tl.int64)
    ob = tl.zeros([BLOCK], tl.int64)
    for j in tl.static_range(MAXD):
        dj = tl.load(meta_ptr + j)
        c = rem % dj
        sa = tl.load(meta_ptr + MAXD + j)
        sb = tl.load(meta_ptr + 2 * MAXD + j)
        oa += c.to(tl.int64) * sa.to(tl.int64)
        ob += c.to(tl.int64) * sb.to(tl.int64)
        rem = rem // dj
    x = tl.load(a_ptr + oa, mask=m, other=0).to(tl.int32)
    y = tl.load(b_ptr + ob, mask=m, other=0).to(tl.int32)
    xa = x.to(tl.uint32)
    ya = y.to(tl.uint32)
    ma = tl.where(x < 0, 0 - xa, xa)
    mb = tl.where(y < 0, 0 - ya, ya)
    g = _eu2_u32(ma, mb, K)
    r = _finish32(ma, mb, g)
    tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty), mask=m)


@triton.jit
def _lcm_bcast64(
    a_ptr,
    b_ptr,
    o_ptr,
    numel,
    meta_ptr,
    BLOCK: tl.constexpr,
    K: tl.constexpr,
    MAXD: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < numel
    rem = offs
    oa = tl.zeros([BLOCK], tl.int64)
    ob = tl.zeros([BLOCK], tl.int64)
    for j in tl.static_range(MAXD):
        dj = tl.load(meta_ptr + j)
        c = rem % dj
        sa = tl.load(meta_ptr + MAXD + j)
        sb = tl.load(meta_ptr + 2 * MAXD + j)
        oa += c.to(tl.int64) * sa.to(tl.int64)
        ob += c.to(tl.int64) * sb.to(tl.int64)
        rem = rem // dj
    x = tl.load(a_ptr + oa, mask=m, other=0).to(tl.int64)
    y = tl.load(b_ptr + ob, mask=m, other=0).to(tl.int64)
    xa = x.to(tl.uint64)
    ya = y.to(tl.uint64)
    ma = tl.where(x < 0, 0 - xa, xa)
    mb = tl.where(y < 0, 0 - ya, ya)
    g = _eu2_u64(ma, mb, K)
    r = _finish64(ma, mb, g)
    tl.store(o_ptr + offs, r.to(o_ptr.dtype.element_ty), mask=m)


# ---------------------------------------------------------------------------
# host wrapper
# ---------------------------------------------------------------------------
def _eff_strides(t, out_shape):
    rank = len(out_shape)
    off = rank - t.dim()
    st = [0] * rank
    for j in range(rank):
        d = j - off
        if 0 <= d < t.dim() and t.shape[d] > 1:
            st[j] = t.stride(d)
    return st


def lcm(self, other):
    with torch_device_fn.device(
        (self if isinstance(self, torch.Tensor) else other).device
    ):
        shape = (
            self.shape
            if self.shape == other.shape
            else torch.broadcast_shapes(self.shape, other.shape)
        )
        dt = torch.promote_types(self.dtype, other.dtype)
        out = torch.empty(shape, dtype=dt, device=self.device)
        numel = out.numel()
        if numel == 0:
            return out

        w64 = dt == torch.int64
        K = _K.get(dt, 24)
        if w64:
            BLOCK, WARPS = _BLOCK64, _WARPS64
        else:
            BLOCK, WARPS = _BLOCK32, _WARPS32

        same = (
            self.shape == other.shape and self.is_contiguous() and other.is_contiguous()
        )
        if same:
            grid = (triton.cdiv(numel, BLOCK),)
            if w64:
                _lcm_flat64[grid](
                    self, other, out, numel, BLOCK=BLOCK, K=K, num_warps=WARPS
                )
            else:
                _lcm_flat32[grid](
                    self, other, out, numel, BLOCK=BLOCK, K=K, num_warps=WARPS
                )
            return out

        rank = len(shape)
        if rank > _MAXD:
            raise RuntimeError(f"lcm: rank {rank} unsupported")
        meta = torch.ones(3 * _MAXD, dtype=torch.int32, device=self.device)
        ea = _eff_strides(self, shape)
        eb = _eff_strides(other, shape)
        for k in range(rank):
            j = rank - 1 - k
            meta[k] = shape[j]
            meta[_MAXD + k] = ea[j]
            meta[2 * _MAXD + k] = eb[j]
        BCAST_BLOCK = 512
        grid = (triton.cdiv(numel, BCAST_BLOCK),)
        if w64:
            _lcm_bcast64[grid](
                self,
                other,
                out,
                numel,
                meta,
                BLOCK=BCAST_BLOCK,
                K=K,
                MAXD=_MAXD,
                num_warps=4,
            )
        else:
            _lcm_bcast32[grid](
                self,
                other,
                out,
                numel,
                meta,
                BLOCK=BCAST_BLOCK,
                K=K,
                MAXD=_MAXD,
                num_warps=4,
            )
        return out


def lcm_(self, other):
    # In-place variant, retained from the implementation this file replaces:
    # `lcm` writes into a fresh tensor and this copies the result back.
    result = lcm(self, other)
    self.copy_(result)
    return self
